import yaml, sys
for f in ['.github/workflows/ci.yml', '.github/workflows/nightly.yml', '.github/workflows/coverage-gardener.yml']:
    try:
        d = yaml.safe_load(open(f))
        print(f, 'OK — jobs:', len(d.get('jobs', {})))
    except Exception as e:
        print(f, 'FAIL', e)
EOF

